/* eslint-disable */

export const protobufPackage = "decentraland.sdk.components.common";

/**
 * Identifies which fullscreen explorer panel OpenExplorerUi targets.
 * EU_SETTINGS holds 0 so an unset `ui` field defaults to the least-intrusive panel.
 */
export enum ExplorerUi {
  EU_SETTINGS = 0,
  EU_MAP = 1,
  EU_BACKPACK = 2,
  EU_CAMERA_REEL = 3,
  EU_COMMUNITIES = 4,
  EU_PLACES = 5,
  EU_EVENTS = 6,
  UNRECOGNIZED = -1,
}

export function explorerUiFromJSON(object: any): ExplorerUi {
  switch (object) {
    case 0:
    case "EU_SETTINGS":
      return ExplorerUi.EU_SETTINGS;
    case 1:
    case "EU_MAP":
      return ExplorerUi.EU_MAP;
    case 2:
    case "EU_BACKPACK":
      return ExplorerUi.EU_BACKPACK;
    case 3:
    case "EU_CAMERA_REEL":
      return ExplorerUi.EU_CAMERA_REEL;
    case 4:
    case "EU_COMMUNITIES":
      return ExplorerUi.EU_COMMUNITIES;
    case 5:
    case "EU_PLACES":
      return ExplorerUi.EU_PLACES;
    case 6:
    case "EU_EVENTS":
      return ExplorerUi.EU_EVENTS;
    case -1:
    case "UNRECOGNIZED":
    default:
      return ExplorerUi.UNRECOGNIZED;
  }
}

export function explorerUiToJSON(object: ExplorerUi): string {
  switch (object) {
    case ExplorerUi.EU_SETTINGS:
      return "EU_SETTINGS";
    case ExplorerUi.EU_MAP:
      return "EU_MAP";
    case ExplorerUi.EU_BACKPACK:
      return "EU_BACKPACK";
    case ExplorerUi.EU_CAMERA_REEL:
      return "EU_CAMERA_REEL";
    case ExplorerUi.EU_COMMUNITIES:
      return "EU_COMMUNITIES";
    case ExplorerUi.EU_PLACES:
      return "EU_PLACES";
    case ExplorerUi.EU_EVENTS:
      return "EU_EVENTS";
    case ExplorerUi.UNRECOGNIZED:
    default:
      return "UNRECOGNIZED";
  }
}
